import re
from dataclasses import dataclass

_NUMBER = r"(?:0|[1-9][0-9]*)"
_IDENT = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    rf"({_NUMBER})\.({_NUMBER})\.({_NUMBER})"
    rf"(?:-({_IDENT}(?:\.{_IDENT})*))?"
    rf"(?:\+({_IDENT}(?:\.{_IDENT})*))?"
)
# Longest first, so ">=" isn't read as ">" followed by "=1.2.3".
_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, prerelease, build = match.groups()
    prerelease = tuple(prerelease.split(".")) if prerelease else ()
    if any(i.isdigit() and len(i) > 1 and i[0] == "0" for i in prerelease):
        raise ValueError(f"invalid version: {text!r}")
    build = tuple(build.split(".")) if build else ()
    return Version(int(major), int(minor), int(patch), prerelease, build)


def _coerce(version: str | Version) -> Version:
    return version if isinstance(version, Version) else parse(version)


def _prerelease_key(prerelease: tuple[str, ...]) -> tuple:
    # A release sorts above every pre-release of the same version. Within a
    # pre-release, (0, n) puts numeric identifiers below alphanumeric (1, s)
    # ones, and tuple comparison makes a shorter matching prefix lower.
    if not prerelease:
        return (1,)
    return (0, tuple((0, int(i)) if i.isdigit() else (1, i) for i in prerelease))


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _coerce(a), _coerce(b)
    key_a = (a.major, a.minor, a.patch, _prerelease_key(a.prerelease))
    key_b = (b.major, b.minor, b.patch, _prerelease_key(b.prerelease))
    return (key_a > key_b) - (key_a < key_b)


def _parse_comparator(text: str) -> list[tuple[str, Version]]:
    """Parse a comparator into equivalent (operator, version) pairs."""
    op = next((o for o in _OPERATORS if text.startswith(o)), "")
    try:
        version = parse(text[len(op):])
    except ValueError:
        raise ValueError(f"invalid comparator: {text!r}") from None
    if op == "^":
        if version.major:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return [(">=", version), ("<", upper)]
    if op == "~":
        return [(">=", version), ("<", Version(version.major, version.minor + 1, 0))]
    return [(op or "=", version)]


def _holds(op: str, version: Version, bound: Version) -> bool:
    result = compare(version, bound)
    if op == "=":
        return result == 0
    if op == ">":
        return result > 0
    if op == ">=":
        return result >= 0
    if op == "<":
        return result < 0
    return result <= 0


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    version = _coerce(version)
    # Parse the whole range up front so an invalid one always raises.
    sets = []
    for set_text in range_.split("||"):
        comparators = [
            pair for text in set_text.split() for pair in _parse_comparator(text)
        ]
        if not comparators:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append(comparators)

    core = (version.major, version.minor, version.patch)
    for comparators in sets:
        if version.prerelease and not any(
            bound.prerelease and (bound.major, bound.minor, bound.patch) == core
            for _, bound in comparators
        ):
            continue
        if all(_holds(op, version, bound) for op, bound in comparators):
            return True
    return False

