import re
from datetime import datetime, timedelta

_MONTHS = "JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC".split()
_DAYS = "SUN MON TUE WED THU FRI SAT".split()

# (low, high, names) per field; names[i] stands for the value low + i.
_FIELDS = [
    (0, 59, []),
    (0, 23, []),
    (1, 31, []),
    (1, 12, _MONTHS),
    (0, 7, _DAYS),
]

_ITEM_RE = re.compile(r"(\*|\w+(?:-\w+)?)(?:/(\w+))?")


def _value(text: str, low: int, high: int, names: list[str]) -> int:
    if text.upper() in names:
        return low + names.index(text.upper())
    if not re.fullmatch(r"[0-9]+", text) or not low <= int(text) <= high:
        raise ValueError(f"invalid value: {text!r}")
    return int(text)


def _parse_field(text: str, low: int, high: int, names: list[str]) -> set[int]:
    values = set()
    for item in text.split(","):
        match = _ITEM_RE.fullmatch(item)
        if match is None:
            raise ValueError(f"invalid item: {item!r}")
        base, step = match.groups()
        if base == "*":
            start, end = low, high
        elif "-" in base:
            start, end = (_value(v, low, high, names) for v in base.split("-"))
            if start > end:
                raise ValueError(f"invalid range: {item!r}")
        else:
            start = end = _value(base, low, high, names)
            if step is not None:
                end = high
        if step is None:
            step = 1
        elif re.fullmatch(r"[0-9]+", step) and int(step) > 0:
            step = int(step)
        else:
            raise ValueError(f"invalid step: {item!r}")
        values.update(range(start, end + 1, step))
    return values


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"expected 5 fields, got {len(fields)}: {expression!r}")
    minutes, hours, days, months, weekdays = (
        _parse_field(text, *spec) for text, spec in zip(fields, _FIELDS)
    )
    if 7 in weekdays:
        weekdays.add(0)
    either_day = fields[2] != "*" and fields[4] != "*"

    def day_matches(moment: datetime) -> bool:
        in_days = moment.day in days
        # isoweekday() is 1-7 for Monday-Sunday; cron counts Sunday as 0.
        in_weekdays = moment.isoweekday() % 7 in weekdays
        return in_days or in_weekdays if either_day else in_days and in_weekdays

    try:
        limit = after.replace(year=after.year + 5)
    except ValueError:  # Feb 29 in a year five years before a non-leap year
        limit = after.replace(year=after.year + 5, day=28)
    except OverflowError:
        limit = datetime.max

    # Step from the next whole minute, skipping a whole month, day, or hour at
    # a time whenever that unit can't match.
    moment = after.replace(second=0, microsecond=0)
    try:
        moment += timedelta(minutes=1)
        while moment <= limit:
            if moment.month not in months:
                year, month = divmod(moment.month, 12)
                moment = moment.replace(
                    year=moment.year + year, month=month + 1, day=1, hour=0, minute=0
                )
            elif not day_matches(moment):
                moment = moment.replace(hour=0, minute=0) + timedelta(days=1)
            elif moment.hour not in hours:
                moment = moment.replace(minute=0) + timedelta(hours=1)
            elif moment.minute not in minutes:
                moment += timedelta(minutes=1)
            else:
                return moment
    except OverflowError:
        pass
    raise ValueError(f"no run within five years: {expression!r}")

