def _read(text: str) -> dict[str, dict[str, str]]:
    """Read sections and raw values, without interpolation."""
    sections: dict[str, dict[str, str]] = {}
    section = None
    key = None  # the key a continuation line would extend
    for lineno, line in enumerate(text.split("\n"), start=1):
        stripped = line.strip()
        if not stripped or stripped[0] in "#;":
            key = None
            continue
        if line[0].isspace() and key is not None:
            section[key] += "\n" + stripped
            continue
        key = None
        if stripped.startswith("[") and stripped.endswith("]"):
            section = sections.setdefault(stripped[1:-1].strip(), {})
            continue
        separators = [i for i in (stripped.find("="), stripped.find(":")) if i >= 0]
        if not separators:
            raise ParseError(lineno, f"expected a section or key: {stripped!r}")
        if section is None:
            raise ParseError(lineno, "key before any section")
        split = min(separators)
        name = stripped[:split].strip().lower()
        if not name:
            raise ParseError(lineno, "empty key")
        section[name] = stripped[split + 1:].strip()
        key = name
    return sections


def _interpolate(
    raw: dict[str, dict[str, str]],
    done: dict[tuple[str, str], str],
    active: set[tuple[str, str]],
    section: str,
    key: str,
) -> str:
    """The interpolated value of ``key`` in ``section``, memoized in ``done``."""
    ref = (section, key)
    if ref in done:
        return done[ref]
    if section not in raw:
        raise InterpolationError(f"no section {section!r}")
    if key not in raw[section]:
        raise InterpolationError(f"no key {key!r} in section {section!r}")
    if ref in active:
        raise InterpolationError(f"cycle at key {key!r} in section {section!r}")
    active.add(ref)

    value = raw[section][key]
    out = []
    i = 0
    while i < len(value):
        if value.startswith("$$", i):
            out.append("$")
            i += 2
            continue
        end = value.find("}", i + 2)
